import { expect, setDefaultTimeout, test } from "bun:test";
import { Camera, type World } from "@dylanebert/shallot";
import { attachTexture, captureTexture } from "@dylanebert/shallot/rendering";
import { MeshRenderPlugin, StandardRenderingPlugin } from "@dylanebert/shallot/standard/rendering";
import { TIMEOUT } from "@dylanebert/shallot/testing";
import { openGpuApp } from "@dylanebert/shallot/testing/gpu";
import { Drop } from "../src/drop";

setDefaultTimeout(TIMEOUT.node);

const WIDTH = 160;
const HEIGHT = 120;

/** Mean row of strongly blue pixels, plus counts of blue and neutral-gray pixels. */
function measure(rgba: Uint8ClampedArray) {
    let blue = 0;
    let gray = 0;
    let rows = 0;
    for (let i = 0; i < WIDTH * HEIGHT; i++) {
        const r = rgba[i * 4]!;
        const g = rgba[i * 4 + 1]!;
        const b = rgba[i * 4 + 2]!;
        if (b > 60 && b > r * 2 && b > g * 1.5) {
            blue++;
            rows += Math.floor(i / WIDTH);
        } else if (r > 50 && Math.abs(r - g) < 12 && Math.abs(g - b) < 12) gray++;
    }
    return { blue, gray, row: blue ? rows / blue : NaN };
}

test("the rendered blue box drops onto the gray floor", async () => {
    const app = await openGpuApp({
        defaults: false,
        plugins: [StandardRenderingPlugin, MeshRenderPlugin, Drop],
    });
    try {
        const world: World = app.world;
        const camera = [...world.query([Camera])][0]!;
        attachTexture(world, camera, { width: WIDTH, height: HEIGHT });
        world.step(1 / 60);
        const start = measure((await captureTexture(world, camera)).rgba);
        for (let i = 0; i < 60 * 5; i++) world.step(1 / 60);
        const landed = measure((await captureTexture(world, camera)).rgba);

        expect(start.blue).toBeGreaterThan(50);
        expect(landed.blue).toBeGreaterThan(50);
        expect(landed.gray).toBeGreaterThan(WIDTH * HEIGHT * 0.1);
        expect(landed.row - start.row).toBeGreaterThan(HEIGHT * 0.15);
        console.log({ start, landed });
    } finally {
        app.dispose();
    }
});
